css:
.memory-story{max-width:880px;margin:auto;color:#21352f;font-family:Pretendard,"Noto Sans KR",Arial,sans-serif;font-size:17px;line-height:1.9;word-break:keep-all;overflow-wrap:anywhere}
.memory-story p{margin:18px 0}.memory-story .eyebrow{font-size:12px;letter-spacing:.14em;font-weight:800;color:#357762;margin:0 0 14px}.memory-story .intro{padding:8px 0 26px;border-bottom:1px solid #d4e2da}.memory-story .intro h2{font-size:34px;line-height:1.4;margin:12px 0 24px;border:0;padding:0}.memory-story .lead{font-size:20px;color:#476157}.memory-story .note,.memory-story .source{font-size:13px;color:#62746c;line-height:1.7}.memory-story a{color:#16624e;text-decoration:underline;text-underline-offset:3px}
.memory-story h2{font-size:26px;line-height:1.5;margin:54px 0 23px;color:#143e30;padding-bottom:13px;border-bottom:2px solid #dbe8df}.memory-story h3{font-size:19px;margin:0 0 10px;line-height:1.5}.memory-story .thesis{background:#143d30;color:#fff;padding:28px 30px;border-radius:16px;margin:32px 0}.memory-story .thesis .eyebrow{color:#b8dfc9}.memory-story .thesis p{margin:12px 0}.memory-story .thesis p:nth-child(2){font-size:21px;line-height:1.75}
.memory-story .cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.memory-story .quote-card{border:1px solid #d3dfd7;border-radius:12px;padding:22px;background:#f7faf7}.memory-story .quote-card span,.memory-story .quote-card small{display:block}.memory-story .quote-card span{font-weight:700;font-size:15px}.memory-story .quote-card strong{display:block;font-size:30px;color:#174b39;margin:8px 0}.memory-story .quote-card small{font-size:13px;color:#62746c}
.memory-story .flow{display:flex;align-items:center;gap:12px;padding:24px 18px;background:#ecf4f0;border-radius:14px;margin:28px 0;text-align:center}.memory-story .flow div{flex:1;min-width:0}.memory-story .flow b{display:block;font-size:16px}.memory-story .flow span{display:block;font-size:13px}.memory-story .flow .arrow{font-size:23px;color:#4b7b62}
.memory-story .table-wrap{overflow-x:auto;margin:26px 0}.memory-story table{width:100%;border-collapse:collapse;font-size:15px;line-height:1.75}.memory-story caption{text-align:left;font-size:18px;font-weight:800;margin-bottom:12px}.memory-story th,.memory-story td{padding:15px 14px;text-align:left;vertical-align:top;border:1px solid #d8e3dc}.memory-story thead th{background:#e5f0e9}.memory-story tbody th{background:#f4f8f5;white-space:nowrap}
.memory-story .caution{background:#fff7e7;border-left:4px solid #c39135;padding:23px 25px;border-radius:0 10px 10px 0;margin:28px 0}.memory-story .caution p{margin:12px 0 0}.memory-story .metric-box{padding:25px;background:#eef4fa;border-radius:12px;margin:26px 0}.memory-story ol{padding-left:25px}.memory-story li{padding-left:3px;margin:12px 0}.memory-story .risk-list section{padding:24px 0;border-bottom:1px solid #dce5df}.memory-story .risk-list p{margin:10px 0 0}
.memory-story .scenario{padding:24px;border-radius:12px;margin:16px 0;border:1px solid #d8e3dc}.memory-story .scenario p{margin:10px 0 0}.memory-story .positive{background:#edf7f0}.memory-story .neutral{background:#f6f6f1}.memory-story .negative{background:#fff2ee}.memory-story .conclusion{background:#143d30;color:#fff;padding:34px;border-radius:16px;margin-top:50px}.memory-story .conclusion .eyebrow{color:#b8dfc9}.memory-story .conclusion h2{color:#fff;border:0;margin:12px 0 24px;padding:0;font-size:29px}.memory-story .conclusion .closing{padding:21px 0;border-top:1px solid #6e9984;border-bottom:1px solid #6e9984;font-size:20px}.memory-story .article-footer{border-top:1px solid #d6e0d9;margin-top:44px;padding-top:20px;color:#66776f;font-size:13px}.memory-story .article-footer p{margin:10px 0}.memory-story .checklist{background:#f4f8f4;border-radius:12px;padding:18px 24px 18px 46px}
@media(max-width:600px){.memory-story{font-size:16px;line-height:1.85}.memory-story .intro h2{font-size:27px}.memory-story .lead{font-size:18px}.memory-story h2{font-size:23px;margin-top:40px}.memory-story .cards{grid-template-columns:1fr}.memory-story .quote-card strong{font-size:28px}.memory-story .thesis,.memory-story .conclusion{padding:24px 20px}.memory-story .thesis p:nth-child(2),.memory-story .conclusion .closing{font-size:18px}.memory-story .conclusion h2{font-size:25px}.memory-story .flow{flex-direction:column}.memory-story .flow .arrow{transform:rotate(90deg)}.memory-story th,.memory-story td{padding:12px 9px}.memory-story table{font-size:13px}}
